describe('Delete Record Confirmation Modal', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="record-list"]').should('be.visible');
  });

  it('should display confirmation modal when delete button is clicked', () => {
    cy.get('[data-testid="record-item"]').first().within(() => {
      cy.get('[data-testid="delete-btn"]').click();
    });

    cy.get('[data-testid="confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="modal-title"]').should('contain', 'Confirm Delete');
    cy.get('[data-testid="modal-message"]').should('contain', 'Are you sure you want to delete this record?');
    cy.get('[data-testid="modal-confirm-btn"]').should('be.visible');
    cy.get('[data-testid="modal-cancel-btn"]').should('be.visible');
  });

  it('should delete record when confirm button is clicked in modal', () => {
    const recordId = 'record-123';
    cy.get(`[data-testid="record-item-${recordId}"]`).should('exist');

    cy.get(`[data-testid="record-item-${recordId}"]`).within(() => {
      cy.get('[data-testid="delete-btn"]').click();
    });

    cy.get('[data-testid="confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="modal-confirm-btn"]').click();

    cy.get('[data-testid="confirmation-modal"]').should('not.exist');
    cy.get(`[data-testid="record-item-${recordId}"]`).should('not.exist');
    cy.get('[data-testid="success-message"]').should('contain', 'Record deleted successfully');
  });

  it('should close modal without deleting when cancel button is clicked', () => {
    const recordId = 'record-456';
    cy.get(`[data-testid="record-item-${recordId}"]`).should('exist');

    cy.get(`[data-testid="record-item-${recordId}"]`).within(() => {
      cy.get('[data-testid="delete-btn"]').click();
    });

    cy.get('[data-testid="confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="modal-cancel-btn"]').click();

    cy.get('[data-testid="confirmation-modal"]').should('not.exist');
    cy.get(`[data-testid="record-item-${recordId}"]`).should('exist');
  });

  it('should close modal when clicking outside the modal (backdrop click)', () => {
    cy.get('[data-testid="record-item"]').first().within(() => {
      cy.get('[data-testid="delete-btn"]').click();
    });

    cy.get('[data-testid="confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="modal-backdrop"]').click({ force: true });

    cy.get('[data-testid="confirmation-modal"]').should('not.exist');
  });

  it('should handle rapid delete button clicks without duplicate modals', () => {
    cy.get('[data-testid="record-item"]').first().within(() => {
      cy.get('[data-testid="delete-btn"]').click();
      cy.get('[data-testid="delete-btn"]').click();
    });

    cy.get('[data-testid="confirmation-modal"]').should('have.length', 1);
  });
});
